const req = $('Webhook: get-status').first().json.body || {};
const n = req.issue_number;
const runs = ($input.first().json && $input.first().json.workflow_runs) || [];

const activeRun = runs.find(r => 
  (r.status === 'in_progress' || r.status === 'queued') &&
  (r.head_branch === `fix/issue-${n}` || (r.display_title || '').includes(`${n}`))
) || runs.find(r => (r.status === 'in_progress' || r.status === 'queued'));

return [{
  json: {
    issue_number: n,
    has_active_run: !!activeRun,
    run_id: activeRun ? activeRun.id : 0
  }
}];

const req = $('Webhook: get-status').first().json.body || {};
const issue = $('GitHub: Get Issue').first().json;
const n = req.issue_number;

if (!issue || issue.message === 'Not Found') {
  return [{
    json: {
      ok: false,
      error: 'issue_not_found',
      spoken: `I could not find issue ${n}.`
    }
  }];
}

const labels = (issue.labels || []).map(l => l.name);
const status = labels.includes('fix-failed') ? 'fix-failed'
  : labels.includes('needs-review') ? 'needs-review'
  : labels.includes('WIP') ? 'WIP' : 'reported';

const allPulls = $('GitHub: Get Pull Requests').all().map(p => p.json).filter(p => p && p.number);
const matchingPull = allPulls.find(p => (p.head && p.head.ref === `fix/issue-${n}`));
const pr_url = matchingPull ? matchingPull.html_url : null;
const pr_number = matchingPull ? matchingPull.number : null;

// Inspect Swarm active step / agent
let activeAgent = null;
let swarmDetails = null;

try {
  const jobsData = $('GitHub: Get Run Jobs').first().json;
  if (jobsData && jobsData.jobs && jobsData.jobs.length > 0) {
    const steps = jobsData.jobs[0].steps || [];
    const inProgressStep = steps.find(s => s.status === 'in_progress');
    if (inProgressStep) {
      const sName = inProgressStep.name || '';
      if (sName.includes('Investigator')) {
        activeAgent = 'Investigator';
      } else if (sName.includes('Reproducer')) {
        activeAgent = 'Reproducer';
      } else if (sName.includes('Coder')) {
        activeAgent = 'Coder';
      } else if (sName.includes('QA Reviewer') || sName.includes('Reviewer')) {
        activeAgent = 'QA Reviewer';
      } else {
        activeAgent = 'Environment Setup';
      }
      swarmDetails = {
        agent: activeAgent,
        step: inProgressStep.name
      };
    }
  }
} catch (e) {}

let spoken = '';
if (status === 'reported') {
  spoken = `Issue ${n} is filed but the fix has not started yet. Say fix issue ${n} to begin.`;
} else if (status === 'WIP') {
  if (activeAgent === 'Investigator') {
    spoken = `Issue ${n} is currently being analyzed by the Investigator Agent to find the root cause.`;
  } else if (activeAgent === 'Reproducer') {
    spoken = `The Reproducer Agent is writing a test to isolate and prove the bug on issue ${n}.`;
  } else if (activeAgent === 'Coder') {
    spoken = `The Coder Agent is currently modifying the files and running tests for issue ${n}.`;
  } else if (activeAgent === 'QA Reviewer') {
    spoken = `The QA Reviewer Agent is running full monorepo regressions and opening the pull request for issue ${n}.`;
  } else {
    spoken = `Issue ${n} is actively running in the swarm sandbox. You can check back shortly.`;
  }
} else if (status === 'needs-review') {
  spoken = pr_number
    ? `Issue ${n} has a fix ready for review. Pull request number ${pr_number} is open.`
    : `Issue ${n} has a fix ready for human review.`;
} else if (status === 'fix-failed') {
  spoken = `The last automated fix attempt for issue ${n} failed. Say fix issue ${n} to retry.`;
}

return [{
  json: {
    ok: true,
    issue_number: n,
    status,
    active_agent: activeAgent,
    swarm: swarmDetails,
    pr_url,
    pr_number,
    spoken
  }
}];
